    @Transient
    public BigDecimal getCalories() {
        if (directCalories != null) return directCalories;
        if (meal != null) return meal.getCaloriesPerServing().multiply(servingsConsumed);
        if (product != null) return getNutrientForProduct(product.getCalories());
        return BigDecimal.ZERO;
    }

    @Transient
    public BigDecimal getProtein() {
        if (directProtein != null) return directProtein;
        if (meal != null) return meal.getProteinPerServing().multiply(servingsConsumed);
        if (product != null) return getNutrientForProduct(product.getProtein());
        return BigDecimal.ZERO;
    }

    @Transient
    public BigDecimal getCarbs() {
        if (directCarbs != null) return directCarbs;
        if (meal != null) return meal.getCarbsPerServing().multiply(servingsConsumed);
        if (product != null) return getNutrientForProduct(product.getCarbs());
        return BigDecimal.ZERO;
    }

    @Transient
    public BigDecimal getFat() {
        if (directFat != null) return directFat;
        if (meal != null) return meal.getFatPerServing().multiply(servingsConsumed);
        if (product != null) return getNutrientForProduct(product.getFat());
        return BigDecimal.ZERO;
    }

    @Transient
    public BigDecimal getFiber() {
        if (directFiber != null) return directFiber;
        if (meal != null) return meal.getFiberPerServing().multiply(servingsConsumed);
        if (product != null) return getNutrientForProduct(product.getFiber());
        return BigDecimal.ZERO;
    }

    @Transient
    public BigDecimal getSugar() {
        if (meal != null) return meal.getSugarPerServing().multiply(servingsConsumed);
        if (product != null) return getNutrientForProduct(product.getSugar());
        return BigDecimal.ZERO;
    }

    @Transient
    public BigDecimal getNetCarbs() {
        if (meal != null) return meal.getNetCarbsPerServing().multiply(servingsConsumed);
        if (product != null) { BigDecimal c = getNutrientForProduct(product.getCarbs()); BigDecimal f = getNutrientForProduct(product.getFiber()); return c.subtract(f); }
        return BigDecimal.ZERO;
    }

    private BigDecimal getNutrientForProduct(BigDecimal nutritionPer100) {
        if (nutritionPer100 == null || productQuantity == null) return BigDecimal.ZERO;
        if (product.getUnit() == Unit.PIECE) return nutritionPer100.multiply(productQuantity);
        return nutritionPer100.multiply(productQuantity.multiply(BigDecimal.TEN));
    }

    @Transient
    public BigDecimal getCost() {
        if (meal != null && servingsConsumed != null) return meal.getCostPerServing().multiply(servingsConsumed);
        if (product != null && productQuantity != null) return product.getPricePerUnit().multiply(productQuantity);
        return BigDecimal.ZERO;
    }

    @Transient
    public String getDisplayName() {
        if (photoDescription != null) return "📷 " + photoDescription;
        if (meal != null) return meal.getName();
        if (product != null) return product.getName();
        return "?";
    }
